T0 = time.time()
KAGGLE = os.path.isdir("/kaggle/working")
WORK = Path("/kaggle/working") if KAGGLE else Path.cwd() / "kaggle_working"
REPO = Path("/tmp/sieve_repo")
INPUT_ROOT = Path("/kaggle/input")
